-- LINOE P0-2 - C. VERIFIKASI POST-APPLY READ-ONLY (hanya SELECT). Proyek: umkmpro-ai.
-- Jalankan setelah B. Semua kolom "harus" wajib sesuai SEBELUM D dijalankan. Kolom "samakan" dibandingkan dengan nilai A.
select
  ((select md5(regexp_replace(p.prosrc,'\s+','','g')) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname='fn_apply_verified_payment' and pg_get_function_identity_arguments(p.oid)='p_transaction_id uuid, p_provider_payment_id text, p_provider_event_id text, p_verified_amount numeric, p_verified_currency text')='fed9cc40c66292168cf7d26b53adaec0') as fungsi_v3_hash_harus_true,
  (select count(*) from pg_proc where proname='fn_apply_verified_payment') as fungsi_jumlah_harus_1,
  (select count(*) from information_schema.columns where table_schema='public' and table_name='prompter_invoices' and column_name='transaction_id' and data_type='uuid' and is_nullable='YES') as kolom_transaction_id_harus_1,
  (select count(*) from pg_indexes where schemaname='public' and tablename='prompter_invoices' and indexname='uq_prompter_invoices_transaction' and indexdef ilike '%unique%' and indexdef ilike '%transaction_id%' and indexdef ilike '%where%') as indeks_unik_parsial_harus_1,
  (select count(*) from pg_constraint where conrelid='public.prompter_invoices'::regclass and contype='f' and confrelid='public.prompter_payment_transactions'::regclass and confdeltype='a' and conkey=(select array_agg(attnum) from pg_attribute where attrelid='public.prompter_invoices'::regclass and attname='transaction_id')) as foreign_key_harus_1,
  coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.prompter_invoices')),false) as rls_invoice_harus_true,
  (select count(*) from pg_policies where schemaname='public' and tablename='prompter_invoices' and policyname='Lihat invoice tenant sendiri' and cmd='SELECT') as policy_invoice_harus_1,
  (select count(*) from information_schema.role_table_grants where table_schema='public' and table_name='prompter_invoices' and grantee in ('anon','authenticated','PUBLIC') and privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')) as hak_tulis_anon_auth_harus_0,
  (select count(*) from pg_proc x where x.oid=(select p.oid from pg_proc p where p.pronamespace='public'::regnamespace and p.proname='fn_apply_verified_payment' and pg_get_function_identity_arguments(p.oid)='p_transaction_id uuid, p_provider_payment_id text, p_provider_event_id text, p_verified_amount numeric, p_verified_currency text') and (has_function_privilege('anon',x.oid,'EXECUTE') or has_function_privilege('authenticated',x.oid,'EXECUTE'))) as fungsi_exec_anon_auth_harus_0,
  coalesce((select has_function_privilege('service_role',x.oid,'EXECUTE') from pg_proc x where x.oid=(select p.oid from pg_proc p where p.pronamespace='public'::regnamespace and p.proname='fn_apply_verified_payment' and pg_get_function_identity_arguments(p.oid)='p_transaction_id uuid, p_provider_payment_id text, p_provider_event_id text, p_verified_amount numeric, p_verified_currency text')),false) as fungsi_exec_service_role_harus_true,
  coalesce((select x.prosecdef and x.proconfig::text like '%search_path=public%' from pg_proc x where x.oid=(select p.oid from pg_proc p where p.pronamespace='public'::regnamespace and p.proname='fn_apply_verified_payment' and pg_get_function_identity_arguments(p.oid)='p_transaction_id uuid, p_provider_payment_id text, p_provider_event_id text, p_verified_amount numeric, p_verified_currency text')),false) as fungsi_secdef_searchpath_harus_true,
  (select count(*) from public.prompter_invoices where transaction_id is null) as invoice_historis_harus_0,
  (select count(*) from public.prompter_invoices where transaction_id is not null) as invoice_terhubung_info,
  (select count(*) from public.prompter_payment_transactions where status='PAID') as paid_info,
  (select count(*) from supabase_migrations.schema_migrations where version='20261103170000') as ledger_p02_sebelum_D_harus_0,
  (select md5(coalesce(string_agg(pg_get_functiondef(p.oid),'|' order by p.oid::regprocedure::text),'')) from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind='f' and p.proname<>'fn_apply_verified_payment' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')) as fungsi_lain_md5_samakan_A,
  (select md5(string_agg(c.oid::text||c.relname,'|' order by c.relname)) from pg_class c where c.relnamespace='public'::regnamespace and c.relkind in ('r','v','m','S')) as tabel_md5_samakan_A,
  (select md5(coalesce(string_agg(c.relname||'.'||t.tgname,'|' order by c.relname,t.tgname),'')) from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and not t.tgisinternal) as trigger_md5_samakan_A,
  (select md5(coalesce(string_agg(tablename||'.'||policyname||'.'||cmd||'.'||coalesce(qual,'')||'.'||coalesce(with_check,''),'|' order by tablename,policyname),'')) from pg_policies where schemaname='public') as policy_md5_samakan_A,
  (select md5(coalesce(string_agg(t::text,'|' order by id),'')) from public.prompter_payment_transactions t) as txn_md5_samakan_A,
  (select md5(coalesce(string_agg(t::text,'|' order by tenant_id),'')) from public.prompter_subscriptions t) as sub_md5_samakan_A;
